mapper.select:
SELECT ar.resource_type AS resourceType, ar.resource_id AS resourceId, MAX(ar.planned_end) AS latestEndTime, MAX(ar.sequence_on_resource) AS maxSequence FROM task_assignment_resource ar INNER JOIN operation_task t ON t.task_id = ar.task_id WHERE ar.resource_type IN
#{resourceType}
AND t.status IN ('SCHEDULED', 'RUNNING', 'PAUSED') GROUP BY ar.resource_type, ar.resource_id

